    const message = $item("0").$node["respostas1"].json["message"];

    if (!message || typeof message !== 'string') {
        return { 
            error: "Mensagem não encontrada ou formato inválido",
            hasMedia: false
        };
    }

    console.log("Processando mensagem:", message);

    // NOVA VERIFICAÇÃO ADICIONADA - Tratar mensagens com links formatados
    if (!message.includes('<imagem>') && !message.includes('<video>') && !message.includes('<audio>') && !message.includes('<documento>')) {
        const linkResult = extractLinkFromFormattedMessage(message);

        if (linkResult && linkResult.success) {
            // Mapear tipo para Evolution API
            let evolutionType;
            switch (linkResult.detectedType) {
                case 'imagem':
                    evolutionType = 'image';
                    break;
                case 'video':
                    evolutionType = 'video';
                    break;
                case 'audio':
                    evolutionType = 'audio';
                    break;
                case 'documento':
                    evolutionType = 'document';
                    break;
                default:
                    evolutionType = 'document';
            }

            return {
                hasMedia: true,
                mediaType: evolutionType,
                url: linkResult.url,
                detectedType: linkResult.detectedType,
                method: linkResult.method,
                originalMessage: message,
                info: "Link extraído de mensagem formatada"
            };
        }
    }

    // Verificar especificamente se tem tag <imagem>
    if (message.includes('<imagem>') && message.includes('</imagem>')) {
        const imageResult = extractImageURL(message);

        if (imageResult) {
            if (imageResult.success) {
                return {
                    hasMedia: true,
                    mediaType: 'image', // Para Evolution API
                    url: imageResult.url,
                    tagType: imageResult.tipo,
                    detectedType: imageResult.detectedType,
                    method: 'image_tag_extraction',
                    originalMessage: message
                };
            } else {
                return {
                    error: imageResult.error,
                    hasMedia: false,
                    debug: { 
                        url: imageResult.url,
                        originalMessage: message 
                    }
                };
            }
        }
    }

    // Verificar outras tags de mídia
    const mediaResults = extractMediaFromTags(message);

    if (mediaResults && mediaResults.length > 0) {
        // Pegar primeira mídia válida
        const validMedia = mediaResults.find(m => m.valid);

        if (validMedia) {
            // Mapear tipo para Evolution API
            let evolutionType;
            switch (validMedia.detectedType) {
                case 'imagem':
                    evolutionType = 'image';
                    break;
                case 'video':
                    evolutionType = 'video';
                    break;
                case 'audio':
                    evolutionType = 'audio';
                    break;
                case 'documento':
                    evolutionType = 'document';
                    break;
                default:
                    evolutionType = 'document';
            }

            return {
                hasMedia: true,
                mediaType: evolutionType,
                url: validMedia.url,
                tagType: validMedia.tagType,
                detectedType: validMedia.detectedType,
                method: 'media_tag_extraction',
                allResults: mediaResults,
                originalMessage: message
            };
